    if len(word) < 3:
        return ""

    # Search from right to left, starting from second-to-last character
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel and it's between two consonants
        if word[i] in vowels:
            # Check if both neighbors are consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
