        for j in range(n):
            if grid[i][j] == 1:
                start_pos = (i, j)
                break
        if start_pos:
            break

    # DFS to find the minimum path
    def dfs(row, col, remaining, current_path):
        if remaining == 0:
            return current_path[:]

        # Try all four directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        min_path = None

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check if the new position is within bounds
            if 0 <= new_row < n and 0 <= new_col < n:
                current_path.append(grid[new_row][new_col])
                result = dfs(new_row, new_col, remaining - 1, current_path)

                # Update min_path if result is better (lexicographically smaller)
                if min_path is None or result < min_path:
                    min_path = result

                current_path.pop()

        return min_path

    result = dfs(start_pos[0], start_pos[1], k - 1, [grid[start_pos[0]][start_pos[1]]])
    return result
